import{_ as l,o as i,c as r,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"CDS Infernalis (Day 2.2) -- Cache Tier Improvements","description":"","frontmatter":{"title":"CDS Infernalis (Day 2.2) -- Cache Tier Improvements","date":"2015-03-06T00:00:00.000Z","updated":"2015-03-07T00:00:00.000Z","tags":["Ceph","Cache Tier","Hit Set","Proxy Mechanism","Data Storage Optimization"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2015/CDS_Infernalis_Day_2.2_--_Cache_Tier_Improvements.md","filePath":"posts/2015/CDS_Infernalis_Day_2.2_--_Cache_Tier_Improvements.md","lastUpdated":1780459816000}'),o={name:"posts/2015/CDS_Infernalis_Day_2.2_--_Cache_Tier_Improvements.md"};function a(n,e,s,p,_,m){return i(),r("div",null,[...e[0]||(e[0]=[t('<h2 id="改进后的中文总结内容" tabindex="-1">改进后的中文总结内容 <a class="header-anchor" href="#改进后的中文总结内容" aria-label="Permalink to &quot;改进后的中文总结内容&quot;">​</a></h2><p>以下是对会议内容的改进总结，确保涵盖了关键细节、主要议题、决定的事项以及后续行动计划。</p><h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题</strong>： Cache Tier改进与Proxy机制讨论</p><p><strong>会议时间</strong>： [请填写会议具体时间]</p><p><strong>参会人员</strong>： [请填写参会人员名单]</p><p><strong>会议内容</strong>：</p><p><strong>一、Cash Tier改进</strong></p><ol><li><p><strong>现状与问题</strong>：</p><ul><li>Intel团队在Hammer周期内对Cash Tier进行了大量改进，主要集中在读操作上，避免了不必要的提升（Promotion）。</li><li>对于写操作的Proxy机制仍需测试和完善。</li><li>当最终决定提升时，仍需阻塞写操作，因为对象尚未提升到Cache层面。</li></ul></li><li><p><strong>改进方向</strong>：</p><ul><li>根据读操作和写操作进行更合理的提升决策，以减少在Base Tier和Cash Tier之间推送数据的次数。</li><li>引入“最近性”概念，类似读操作的策略，对写操作进行优化。</li></ul></li><li><p><strong>具体方案</strong>：</p><ul><li>跟踪不同类型的I/O操作，区分读和写操作，以及顺序读和顺序写操作。</li><li>基于I/O类型进行提升决策，例如，对于大量读操作但从未写入的对象，可能不需要提升；对于只写入但无读操作的对象，根据性能指标可能需要提升。</li><li>使用近似计数Bloom过滤器，用于跟踪冷数据，而将热数据存储在哈希表中，以便进行精确计数。</li></ul></li></ol><p><strong>二、Hit Set改进</strong></p><ol><li><p><strong>现状与问题</strong>：</p><ul><li>Hit Set目前只能覆盖固定时间间隔（例如1小时），且只能告知是否有一个或多个I/O操作，无法提供具体数量。</li><li>无法区分对象在1小时内被读取一次和被读取100,000次的情况。</li></ul></li><li><p><strong>改进方向</strong>：</p><ul><li>使用混合哈希表和布隆过滤器，捕获热点数据和非热点数据。</li><li>使用近似计数Bloom过滤器，以更精确地跟踪数据。</li></ul></li><li><p><strong>具体方案</strong>：</p><ul><li>哈希表用于存储热点数据，布隆过滤器用于存储非热点数据。</li><li>使用近似计数Bloom过滤器，用于跟踪对象的热度，并决定何时将对象从哈希表移动到布隆过滤器。</li></ul></li></ol><p><strong>三、行动计划</strong></p><ol><li>完成写操作的Proxy机制测试。</li><li>实现基于I/O类型的提升决策。</li><li>研究并确定实现频繁项和数据流查找的最佳方法。</li><li>实现近似计数Bloom过滤器。</li></ol><p><strong>四、后续工作</strong></p><ol><li>[请填写后续工作安排，例如：分配任务、确定时间节点等。]</li></ol><p><strong>五、备注</strong></p><ol><li>会议中提到的技术词汇，如“Hit Set”、“Promotion”、“Bloom filter”等，请参考相关资料进行了解。</li><li>会议中提到的相关论文和资料，请参考以下链接： <ul><li><a href="https://www.cs.cmu.edu/~michalb/papers/counting.pdf" target="_blank" rel="noreferrer">Approximate Counting Bloom Filters</a></li><li><a href="https://www.cs.cmu.edu/~michalb/papers/min-mis.pdf" target="_blank" rel="noreferrer">Min-Mis Rate Curves</a></li></ul></li></ol><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h3><p>本次会议重点讨论了Ceph中Cache Tier的改进，包括Proxy机制的测试和完善、基于I/O类型的提升决策、Hit Set的改进以及近似计数Bloom过滤器的实现。会议还确定了后续的行动计划，包括测试、研究和实施相关改进。</p>',19)])])}const g=l(o,[["render",a]]);export{c as __pageData,g as default};
